//! Only artifacts generated by build.rs and embedded in the signed app.
use super::runtime::wasm::precompiled::{TrustedPrecompiled, VerifiedComponent};

type Artifact = ([u8; 32], [u8; 32], &'static str, &'static [u8]);
const BUNDLED: &[Artifact] = include!(concat!(
    env!("OUT_DIR"),
    "/plugin-precompiled/precompiled.rs"
));

pub(super) fn find(component: &VerifiedComponent) -> Option<TrustedPrecompiled<'static>> {
    BUNDLED
        .iter()
        .find(|artifact| artifact.0 == component.digest())
        .map(|artifact| {
            // SAFETY: these bytes are generated by our build dependency, outside
            // plugin packages, and compiled into our signed app. Never read this
            // table from a third-party package or a frontend-supplied path.
            unsafe { TrustedPrecompiled::new(artifact.0, artifact.1, artifact.2, artifact.3) }
        })
}
